-- Applied via run_sql (project-specific URL). Read-only Instagram comment sync every 15 minutes (minutes 08, 23, 38, 53 UTC).
SELECT cron.schedule('marketing-instagram-comments-every-15-min','8-59/15 * * * *', $job$ SELECT net.http_post(url:='https://project--945f60ba-be65-42ad-a5a3-dc640ed8b1b3.lovable.app/api/public/hooks/marketing-comments',headers:=jsonb_build_object('Content-Type','application/json','x-publish-secret',(SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name='marketing_enrich_secret' LIMIT 1)),body:='{}'::jsonb,timeout_milliseconds:=120000) $job$);
